static void fcallCommandGeneric(client *c, int ro) {
    functionsLibCtx *live_ctx = curr_functions_lib_ctx;
    robj *function_name = c->argv[1];
    functionInfo *fi = dictFetchValue(live_ctx->functions, function_name->ptr);
    if (!fi || !functionsFunctionExists(live_ctx, function_name->ptr)) {
        sds missing = functionsDescribeMissingFunction(function_name->ptr);
        addReplyError(c, missing);
        sdsfree(missing);
        return;
    }
    engine *engine = fi->li->ei->engine;

    long long numkeys;
    /* Get the number of arguments that are keys */
    if (functionsValidateKeyCount(c, 2, &numkeys) != C_OK) {
        return;
    }

    scriptRunCtx run_ctx;

    if (functionsScriptPrepareForRun(&run_ctx, fi->li->ei->c, c, fi->name, fi->f_flags, ro) != C_OK)
        return;

    engine->call(&run_ctx, engine->engine_ctx, fi->function, c->argv + 3, numkeys,
                 c->argv + 3 + numkeys, c->argc - 3 - numkeys);
    functionsScriptResetRun(&run_ctx);
}

/*
 * FCALL <FUNCTION NAME> nkeys <key1 .. keyn> <arg1 .. argn>
